INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷80·晋高祖纪·天福六年十二月奏十一月战事", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/179342146c1d78cfe3d5641c28e7db199f4e8b59/content/books/zizhi-tongjian/vol-282/year-0941/part-05/sources/library/jiuwudaishi-080-an-congjin-battle/source.txt", "note": "《旧五代史》卷80·晋高祖纪·天福六年十二月奏十一月战事，段落 jiu-wudaishi-205deb4a7860-p001965；已核上下文及传主，纸本及异文待核。", "id": "730c5b92-8047-5888-94e1-7917e27fa2d8"}, {"title": "旧五代史·卷98·安从进传·预备空名宣敕", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/179342146c1d78cfe3d5641c28e7db199f4e8b59/content/books/zizhi-tongjian/vol-282/year-0941/part-05/sources/library/jiuwudaishi-098-an-congjin-orders/source.txt", "note": "《旧五代史》卷98·安从进传·预备空名宣敕，段落 jiu-wudaishi-205deb4a7860-p002396；已核上下文及传主，纸本及异文待核。", "id": "ec871bb7-f282-5266-bd08-f2897ae1a061"}, {"title": "资治通鉴·卷282·天福六年九月至十二月", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/179342146c1d78cfe3d5641c28e7db199f4e8b59/content/books/zizhi-tongjian/vol-282/year-0941/part-05/sources/library/tongjian-282-941-autumn-winter/source.txt", "note": "《资治通鉴》卷282·天福六年九月至十二月，段落 zizhi-tongjian-a63549944a71-p003358；已核上下文及传主，纸本及异文待核。", "id": "a0bfbd8b-2660-5734-857f-5b507a1eb304"}, {"title": "新五代史·卷51·安从进传·预备空名宣敕", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/179342146c1d78cfe3d5641c28e7db199f4e8b59/content/books/zizhi-tongjian/vol-282/year-0941/part-05/sources/library/xinwudaishi-051-an-congjin-orders/source.txt", "note": "《新五代史》卷51·安从进传·预备空名宣敕，段落 xin-wudaishi-b08f244b9241-p002008；已核上下文及传主，纸本及异文待核。", "id": "4aea6e7b-d58f-5ed6-aa1c-7b8c912e2f2a"}, {"title": "新五代史·卷51·安从进传·出兵与败退", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/179342146c1d78cfe3d5641c28e7db199f4e8b59/content/books/zizhi-tongjian/vol-282/year-0941/part-05/sources/library/xinwudaishi-051-an-congjin-retreat/source.txt", "note": "《新五代史》卷51·安从进传·出兵与败退，段落 xin-wudaishi-b08f244b9241-p002009；已核上下文及传主，纸本及异文待核。", "id": "083e5247-8a86-5fe6-84ce-24904f8430f7"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "杨彦询", "aliases": ["楊彥詢"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：杨彦询，获任副留守者。", "biography": null, "status": "draft", "id": "d829ba3f-56da-5e63-8216-680ff37456ce"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "王延羲", "aliases": ["王曦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国宗室，王继鹏的叔父，曾任左仆射、同平章事。939年被政变军队拥立，自称威武节度使、闽国王，更名王曦，改元永隆。生卒年暂未核实。", "biography": null, "status": "draft", "id": "e706d6ae-56f4-5e44-9d24-f3060ae87cbb"}, {"name": "王亚澄", "aliases": ["王亞澄"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽王王延羲的儿子。941年四月被任命为同平章事，主管六军诸卫。生卒年未载。", "biography": null, "status": "draft", "id": "bdfe7b21-c8f9-5a2a-8792-e061e8da5652"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "白承福", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吐谷浑酋长。941年四月辛巳，北京留守李德珫派牙校带领白承福入朝。原文没有说明他是否就是此前归附后晋的某支未具名部众首领。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "404c2172-d65b-534b-aed5-a6e9f5850b6a"}, {"name": "安重荣", "aliases": ["安重榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安重荣，转投者。", "biography": null, "status": "draft", "id": "7309cd08-206a-5781-8eaa-527f54f64299"}, {"name": "王延政", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王延政，都教练使、赴建州抚慰者。", "biography": null, "status": "draft", "id": "83601670-f3dc-5559-b599-e39bda91eb6c"}, {"name": "李敏（闽国宰相）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 941, "description": "闽国同平章事。资治通鉴941年十月条下记他去世。与早已去世、曾名李敏的唐昭宗分开建档；是否与早期闽国尚书、李春燕之父李敏为同一人，另待史料校核。出生年未载。", "biography": null, "status": "draft", "id": "a6d4d0de-1821-59e5-87cd-611e92db037b"}, {"name": "和凝", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：和凝，翰林学士、建议者。", "biography": null, "status": "draft", "id": "f4084e8d-6018-5318-8498-525d067ebeda"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "安从进", "aliases": ["安從進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安从进，受询的侍卫都指挥使。", "biography": null, "status": "draft", "id": "3b1f48e5-6ce0-58cd-add7-1bdf9f0d4812"}, {"name": "武延翰", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋唐州刺史。941年十一月向朝廷奏报安从进举兵攻邓州。生卒年未载。", "biography": null, "status": "draft", "id": "b7aefb55-07e1-5819-89b1-0624cc02bc14"}, {"name": "张从恩", "aliases": ["張從恩"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，曾任澶州防御使。939年正月任后晋枢密副使。生卒年未载。", "biography": null, "status": "draft", "id": "e1e909ad-c88c-54a5-941c-6116c704a870"}, {"name": "焦继勋", "aliases": ["焦繼勛"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋武德使。941年十一月受石重贵派遣，与张从恩、郭金海、陈思让领大梁兵讨伐安从进；旧史奏报中也列其参与唐州以南战役。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "a397d94d-0b6a-5593-9f5e-c39132813767"}, {"name": "郭金海", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋护圣都指挥使，原属突厥。941年十一月受石重贵派遣讨伐安从进，丁丑获任先锋使。生卒年未载。", "biography": null, "status": "draft", "id": "9379345e-8f04-552c-a99c-e5d8a9dc7cf4"}, {"name": "陈思让", "aliases": ["陳思讓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋作坊使，幽州人。941年十一月受石重贵派遣讨伐安从进，丁丑获任先锋军监军。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "59feec41-432b-5d18-829a-46def9523238"}, {"name": "李建崇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋申州刺史。941年十一月所率军队为石重贵遣兵赴叶县会合讨伐安从进的对象。新五代史记他与郭金海等受空名敕出讨，在湖阳遇安从进军。生卒年未载。", "biography": null, "status": "draft", "id": "a39f6abf-e365-56ac-902d-aea8e9bf4030"}, {"name": "高行周", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化三年条所见人物：高行周。", "biography": null, "status": "draft", "id": "659c5f83-09bc-5282-8f02-4c7fa0a62729"}, {"name": "宋彦筠", "aliases": ["宋彥筠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋前同州节度使，滑州人。941年十一月丁丑受任高行周的副将，参与南面军前讨伐安从进的部署。生卒年未载。", "biography": null, "status": "draft", "id": "a66a316a-5777-5c2c-aaa8-0e523f85477d"}, {"name": "李德珫", "aliases": ["李德充"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋建雄节度使。940年三月调任北都留守。《旧五代史》同次从晋州到北京的调任写作李德充，按任职与行动对应识别为同一人，保留原文字形说明。生卒年未载。", "biography": null, "status": "draft", "id": "0263c149-1d66-5360-8ad2-9b565aa3d34e"}, {"name": "安审晖", "aliases": ["安審暉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安审琦的兄长。940年任保大节度使，受命副马全节讨李金全，追击南唐军，黄花谷、云梦战事获胜。《新五代史》《旧五代史》写安審暉，展示使用简体。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "9e82b7a2-6a78-5042-8d8a-b030debbc67f"}, {"name": "安弘义", "aliases": ["安弘義", "安宏义", "安宏義"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安从进的儿子，牙内都指挥使。941年十一月癸未花山战役中被张从恩军俘获。旧史对应奏报写安宏義，姓名字形作为同次战役的异写保留。生卒年未载。", "biography": null, "status": "draft", "id": "16a73d3f-3b31-5b7a-b762-8c52b7041fe3"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
