": 941, "time_original": "941年九月条下，具体日期未载", "dynasty": "五代十国", "description": "王延羲任王亚澄为威武节度使、兼中书令，改封长乐王。", "phases": [], "location_name": "闽国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "68bc50b1-e904-5ad4-9a04-d987f1b008bc"}, {"title": "刘知远派郭威奉诏劝白承福离开安重荣，许以节度使职位", "start_year": 941, "end_year": 941, "time_original": "941年十月白承福归附以前，具体日期未载", "dynasty": "五代十国", "description": "刘知远派郭威奉诏劝白承福离开安重荣，许以节度使职位。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "6a9a5e94-46b0-5e7d-a9ca-ae094442118a"}, {"title": "郭威回报刘知远，建议以厚礼招来白承福", "start_year": 941, "end_year": 941, "time_original": "941年十月白承福归附以前，具体日期未载", "dynasty": "五代十国", "description": "郭威回报，认为安重荣只用袍裤赠给部众，若要招来白承福，应给更多财物。刘知远接受建议。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "f023bd1f-a844-56ae-a93d-4a577c39eb09"}, {"title": "刘知远派人警告白承福，要求停止支持安重荣并归朝廷", "start_year": 941, "end_year": 941, "time_original": "941年十月白承福归附以前，具体日期未载", "dynasty": "五代十国", "description": "刘知远派人告诉白承福，朝廷此前已将他们划归契丹，南来助安重荣会陷入叛逆；安重荣即将败亡，应尽早归朝廷，以免被用兵后南北无所归。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "6a84b271-2cac-5d92-82ac-c9d05913f83f"}, {"title": "白承福害怕，率部归附刘知远", "start_year": 941, "end_year": 941, "time_original": "941年冬十月，具体日期未载", "dynasty": "五代十国", "description": "白承福害怕，率部归附刘知远。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown"